import numpy as np


def strategy(hist, state, pos, ind):
    close = hist.close
    macd_line, signal_line, histogram = ind.macd(close, 12, 26, 9)

    if len(hist) < 2:
        return {"target": pos, "stop": None, "take": None}

    # Detect MACD crosses
    bullish_cross = macd_line[-2] <= signal_line[-2] and macd_line[-1] > signal_line[-1]
    bearish_cross = macd_line[-2] >= signal_line[-2] and macd_line[-1] < signal_line[-1]

    in_trade = state.get("in_trade", False)

    if not in_trade:
        # Entry: bullish cross while flat
        if bullish_cross and pos == 0.0:
            entry_price = close[-1]
            entry_atr = ind.atr(hist, 14)[-1]
            state["in_trade"] = True
            state["entry_price"] = entry_price
            state["entry_atr"] = entry_atr
            state["last_add_price"] = entry_price
            state["pyramid_count"] = 0
            state["box_anchor"] = entry_price

            stop = entry_price - entry_atr
            take = entry_price + 2.0 * entry_atr
            return {"target": 0.5, "stop": stop, "take": take}
        else:
            return {"target": pos, "stop": None, "take": None}
    else:
        # If position was closed by stop/take, reset
        if pos == 0.0:
            state["in_trade"] = False
            return {"target": 0.0, "stop": None, "take": None}

        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]
        last_add_price = state["last_add_price"]
        pyramid_count = state["pyramid_count"]
        box_anchor = state["box_anchor"]

        # Bearish MACD cross exits the trade
        if bearish_cross:
            state["in_trade"] = False
            return {"target": 0.0, "stop": None, "take": None}

        # Ratchet the box forward by 2 ATR steps
        while close[-1] >= box_anchor + 2.0 * entry_atr:
            box_anchor += 2.0 * entry_atr
        state["box_anchor"] = box_anchor

        # Pyramid: add half size when close is 2 ATR above last add price
        target = pos
        if pyramid_count < 2 and close[-1] >= last_add_price + 2.0 * entry_atr:
            new_target = min(pos + 0.5, 1.0)
            if new_target > pos:
                target = new_target
                state["last_add_price"] = close[-1]
                state["pyramid_count"] = pyramid_count + 1

        # Box stop and take-profit
        stop = box_anchor - entry_atr
        take = box_anchor + 2.0 * entry_atr

        return {"target": target, "stop": stop, "take": take}

