def strategy(hist, state, pos, ind):
    macd_line, signal_line, histogram = ind.macd(hist.close, 8, 17, 9)

    current_macd = macd_line[-1]
    current_signal = signal_line[-1]
    prev_macd = macd_line[-2]
    prev_signal = signal_line[-2]

    # Not enough data yet
    if np.isnan(current_macd) or np.isnan(current_signal) or np.isnan(prev_macd) or np.isnan(prev_signal):
        return {"target": pos, "stop": None, "take": None}

    current_close = hist.close[-1]

    # If flat, look for long entry on bullish MACD cross
    if pos == 0:
        # Cross above: at-or-below on previous bar, strictly above now
        if prev_macd <= prev_signal and current_macd > current_signal:
            entry_atr = ind.atr(hist, 14)[-1]
            state["entry_price"] = float(current_close)
            state["entry_atr"] = float(entry_atr)
            state["be_active"] = False
            return {"target": 0.5, "stop": None, "take": None}
        return {"target": 0.0, "stop": None, "take": None}

    # If long, manage the position
    if pos > 0:
        # MACD bearish flip: bail at the open
        if prev_macd >= prev_signal and current_macd < current_signal:
            if "entry_price" in state:
                del state["entry_price"]
            if "entry_atr" in state:
                del state["entry_atr"]
            if "be_active" in state:
                del state["be_active"]
            return {"target": 0.0, "stop": None, "take": None}

        entry_price = state.get("entry_price", 0.0)
        entry_atr = state.get("entry_atr", 0.0)
        be_active = state.get("be_active", False)

        # Check if price closed at least 1.5 ATR in the green
        if not be_active:
            if current_close >= entry_price + 1.5 * entry_atr:
                state["be_active"] = True
                be_active = True

        # Send breakeven stop if active
        if be_active:
            return {"target": pos, "stop": entry_price, "take": None}

        return {"target": pos, "stop": None, "take": None}

    # Should not happen (long-only), but close any unexpected short
    return {"target": 0.0, "stop": None, "take": None}

