def strategy(hist, state, pos, ind) -> dict:
    atr = ind.atr(hist, 14)
    current_atr = atr[-1]

    if len(hist) < 33:
        return {"target": pos, "stop": None, "take": None}

    # Prior 32-bar box (the 32 bars BEFORE the current bar)
    prior_high_val = ind.highest(hist.high, 32)[-2]
    prior_low_val = ind.lowest(hist.low, 32)[-2]

    box_height = prior_high_val - prior_low_val
    close = hist.close[-1]

    # Signals: close breaches box extreme AND box height <= 6 ATR
    long_signal = (close > prior_high_val) and (box_height <= 6.0 * current_atr)
    short_signal = (close < prior_low_val) and (box_height <= 6.0 * current_atr)

    # Clean up state if position was closed by stop/take
    if pos == 0.0 and "direction" in state:
        del state["direction"]
        if "entry_price" in state:
            del state["entry_price"]
        if "entry_atr" in state:
            del state["entry_atr"]
        if "extreme" in state:
            del state["extreme"]

    # Flat: look for entry
    if pos == 0.0:
        if long_signal:
            state["direction"] = 1
            state["entry_price"] = close
            state["entry_atr"] = current_atr
            stop = close - 2.0 * current_atr
            return {"target": 0.5, "stop": stop, "take": None}
        elif short_signal:
            state["direction"] = -1
            state["entry_price"] = close
            state["entry_atr"] = current_atr
            stop = close + 2.0 * current_atr
            return {"target": -0.5, "stop": stop, "take": None}
        else:
            return {"target": 0.0, "stop": None, "take": None}

    # In a trade
    direction = state.get("direction", 0)
    entry_price = state.get("entry_price", 0.0)
    entry_atr = state.get("entry_atr", 0.0)

    # Opposite signal closes the position
    if direction == 1 and short_signal:
        del state["direction"]
        if "entry_price" in state:
            del state["entry_price"]
        if "entry_atr" in state:
            del state["entry_atr"]
        if "extreme" in state:
            del state["extreme"]
        return {"target": 0.0, "stop": None, "take": None}
    elif direction == -1 and long_signal:
        del state["direction"]
        if "entry_price" in state:
            del state["entry_price"]
        if "entry_atr" in state:
            del state["entry_atr"]
        if "extreme" in state:
            del state["extreme"]
        return {"target": 0.0, "stop": None, "take": None}

    # Update trailing extreme and compute stop
    if direction == 1:
        if "extreme" not in state:
            state["extreme"] = hist.high[-1]
        else:
            if hist.high[-1] > state["extreme"]:
                state["extreme"] = hist.high[-1]
        extreme = state["extreme"]
        hard_stop = entry_price - 2.0 * entry_atr
        trail_stop = extreme - 1.5 * entry_atr
        stop = max(hard_stop, trail_stop)
        return {"target": pos, "stop": stop, "take": None}
    elif direction == -1:
        if "extreme" not in state:
            state["extreme"] = hist.low[-1]
        else:
            if hist.low[-1] < state["extreme"]:
                state["extreme"] = hist.low[-1]
        extreme = state["extreme"]
        hard_stop = entry_price + 2.0 * entry_atr
        trail_stop = extreme + 1.5 * entry_atr
        stop = min(hard_stop, trail_stop)
        return {"target": pos, "stop": stop, "take": None}

    return {"target": pos, "stop": None, "take": None}

