def strategy(hist, state, pos, ind):
    t = len(hist) - 1

    if t < 49:
        return {"target": pos, "stop": None, "take": None}

    # Donchian channel: prior 48 bars (excluding current bar)
    prior_high = ind.highest(hist.high, 48)[-2]
    prior_low = ind.lowest(hist.low, 48)[-2]
    close = hist.close[-1]

    long_signal = close > prior_high
    short_signal = close < prior_low

    if pos != 0:
        # Currently in a trade
        direction = 1 if pos > 0 else -1
        entry_atr = state["entry_atr"]
        entry_bar = state["entry_bar"]

        # Update best price (ratchet)
        if direction == 1:
            best = max(state["best_price"], hist.high[-1])
        else:
            best = min(state["best_price"], hist.low[-1])
        state["best_price"] = best

        # Exit: opposite signal
        if (direction == 1 and short_signal) or (direction == -1 and long_signal):
            del state["entry_bar"]
            del state["entry_atr"]
            del state["best_price"]
            return {"target": 0.0, "stop": None, "take": None}

        # Exit: 32-bar timeout (exit at open of the 32nd bar in trade)
        if t - entry_bar >= 31:
            del state["entry_bar"]
            del state["entry_atr"]
            del state["best_price"]
            return {"target": 0.0, "stop": None, "take": None}

        # Trailing stop: 2 ATR behind best price
        if direction == 1:
            stop_level = best - 2.0 * entry_atr
        else:
            stop_level = best + 2.0 * entry_atr

        return {"target": pos, "stop": stop_level, "take": None}

    else:
        # Flat: look for Donchian breakout entry
        if long_signal:
            atr_val = ind.atr(hist, 14)[-1]
            state["entry_bar"] = t
            state["entry_atr"] = atr_val
            state["best_price"] = close
            stop_level = close - 2.0 * atr_val
            return {"target": 0.5, "stop": stop_level, "take": None}
        elif short_signal:
            atr_val = ind.atr(hist, 14)[-1]
            state["entry_bar"] = t
            state["entry_atr"] = atr_val
            state["best_price"] = close
            stop_level = close + 2.0 * atr_val
            return {"target": -0.5, "stop": stop_level, "take": None}

        return {"target": 0.0, "stop": None, "take": None}

import numpy as np


def strategy(hist, state, pos, ind):
    # Compute MACD(5, 35, 5) on 15-min closes
    macd_line, signal_line, histogram = ind.macd(hist.close, 5, 35, 5)

    # Safety: ensure MACD values are valid
    if np.isnan(macd_line[-1]) or np.isnan(signal_line[-1]):
        return {"target": pos, "stop": None, "take": None}
    if np.isnan(macd_line[-2]) or np.isnan(signal_line[-2]):
        return {"target": pos, "stop": None, "take": None}

    # MACD cross detection
    macd_cross_up = (macd_line[-2] <= signal_line[-2]) and (macd_line[-1] > signal_line[-1])
    macd_cross_down = (macd_line[-2] >= signal_line[-2]) and (macd_line[-1] < signal_line[-1])

    # If we are in a long trade
    if pos > 0:
        entry_price = state.get("entry_price", 0.0)
        entry_atr = state.get("entry_atr", 1.0)
        highest_high = state.get("highest_high", 0.0)
        scaled_out = state.get("scaled_out", False)

        # Update highest high with current bar's high
        current_high = hist.high[-1]
        if current_high > highest_high:
            highest_high = current_high
            state["highest_high"] = highest_high

        # Trailing stop: highest high since entry minus 3 * entry ATR
        trail_stop = highest_high - 3.0 * entry_atr

        # Opposite signal (MACD crosses below signal) → go flat
        if macd_cross_down:
            for k in ("entry_price", "entry_atr", "highest_high", "scaled_out"):
                if k in state:
                    del state[k]
            return {"target": 0.0, "stop": None, "take": None}

        # Partial exit: bar closes at least 3 ATR in profit → bank half
        if not scaled_out and hist.close[-1] >= entry_price + 3.0 * entry_atr:
            state["scaled_out"] = True
            # Half of 0.75 = 0.375, rounds to 0.40 on the 0.05 grid
            return {"target": 0.40, "stop": trail_stop, "take": None}

        # Normal bar: maintain position with trailing stop
        return {"target": pos, "stop": trail_stop, "take": None}

    # If flat, look for long entry
    if pos == 0.0:
        # 1-hour trend filter: last completed 1h close above 20 EMA
        htf = hist.htf(60)
        if len(htf) < 20:
            return {"target": pos, "stop": None, "take": None}

        ema_20_1h = ind.ema(htf.close, 20)
        htf_ema_val = ema_20_1h[-1]

        if np.isnan(htf_ema_val):
            return {"target": pos, "stop": None, "take": None}

        trend_up = htf.close[-1] > htf_ema_val

        # Entry: MACD crosses above signal AND trend filter is bullish
        if macd_cross_up and trend_up:
            atr_arr = ind.atr(hist, 14)
            entry_atr_val = atr_arr[-1]

            if np.isnan(entry_atr_val) or entry_atr_val <= 0:
                return {"target": pos, "stop": None, "take": None}

            # Store trade state
            state["entry_price"] = float(hist.close[-1])
            state["entry_atr"] = float(entry_atr_val)
            state["highest_high"] = float(hist.high[-1])
            state["scaled_out"] = False

            return {"target": 0.75, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

