def strategy(hist, state, pos, ind):
    t = len(hist) - 1

    if len(hist) < 2:
        return {"target": 0.0, "stop": None, "take": None}

    # Compute MACD(5, 35, 5)
    macd_line, signal_line, histogram = ind.macd(hist.close, 5, 35, 5)

    h_now = histogram[-1]
    h_prev = histogram[-2]

    # MACD histogram cross detection
    bull_cross = (h_prev <= 0.0) and (h_now > 0.0)
    bear_cross = (h_prev >= 0.0) and (h_now < 0.0)

    # ATR
    atr_arr = ind.atr(hist, 14)
    current_atr = atr_arr[-1]

    # Detect trade end for cooldown
    prev_pos = state.get("prev_pos", 0.0)
    if prev_pos != 0.0 and pos == 0.0:
        state["cooldown_until"] = t + 4
        for k in ("entry_atr", "direction", "extreme_price", "last_add_price", "adds_done"):
            if k in state:
                del state[k]

    state["prev_pos"] = pos

    # --- In a trade ---
    if pos != 0.0:
        direction = int(state.get("direction", 1))
        entry_atr = state.get("entry_atr", current_atr)
        extreme = state.get("extreme_price", hist.close[-1])
        last_add_price = state.get("last_add_price", hist.close[-1])
        adds_done = int(state.get("adds_done", 0))

        # Update extreme price
        if direction == 1:
            if hist.high[-1] > extreme:
                extreme = hist.high[-1]
        else:
            if hist.low[-1] < extreme:
                extreme = hist.low[-1]
        state["extreme_price"] = extreme

        # Opposite signal → bail
        if (direction == 1 and bear_cross) or (direction == -1 and bull_cross):
            return {"target": 0.0, "stop": None, "take": None}

        # Pyramid check
        if adds_done < 2:
            can_add = False
            if direction == 1:
                can_add = hist.close[-1] >= last_add_price + entry_atr
            else:
                can_add = hist.close[-1] <= last_add_price - entry_atr

            if can_add:
                if direction == 1:
                    new_pos = min(pos + 0.25, 0.75)
                    stop = extreme - 4.0 * entry_atr
                else:
                    new_pos = max(pos - 0.25, -0.75)
                    stop = extreme + 4.0 * entry_atr
                state["adds_done"] = adds_done + 1
                state["last_add_price"] = hist.close[-1]
                return {"target": new_pos, "stop": stop, "take": None}

        # Trail stop
        if direction == 1:
            stop = extreme - 4.0 * entry_atr
        else:
            stop = extreme + 4.0 * entry_atr

        return {"target": pos, "stop": stop, "take": None}

    # --- Flat: check for new entry ---
    cooldown_until = state.get("cooldown_until", -1)
    if t <= cooldown_until:
        return {"target": 0.0, "stop": None, "take": None}

    if current_atr <= 0.0:
        return {"target": 0.0, "stop": None, "take": None}

    if bull_cross:
        state["direction"] = 1
        state["entry_atr"] = current_atr
        state["extreme_price"] = hist.high[-1]
        state["last_add_price"] = hist.close[-1]
        state["adds_done"] = 0
        stop = hist.close[-1] - 4.0 * current_atr
        return {"target": 0.25, "stop": stop, "take": None}

    if bear_cross:
        state["direction"] = -1
        state["entry_atr"] = current_atr
        state["extreme_price"] = hist.low[-1]
        state["last_add_price"] = hist.close[-1]
        state["adds_done"] = 0
        stop = hist.close[-1] + 4.0 * current_atr
        return {"target": -0.25, "stop": stop, "take": None}

    return {"target": 0.0, "stop": None, "take": None}

