        direction = state['direction']
        entry_atr = state['entry_atr']
        anchor = state['anchor']
        entry_bar = state['entry_bar']

        # Hard time stop: 64 bars since signal bar
        if t - entry_bar >= 64:
            state['in_trade'] = 0
            return {"target": 0.0, "stop": None, "take": None}

        # Opposite MACD cross exits flat
        if direction == 1:
            # Long: MACD crosses below signal
            if macd_line[-2] >= signal_line[-2] and macd_line[-1] < signal_line[-1]:
                state['in_trade'] = 0
                return {"target": 0.0, "stop": None, "take": None}
