            if close >= anchor + entry_atr:
                anchor = anchor + entry_atr
                state['anchor'] = anchor
        else:
            if close <= anchor - entry_atr:
                anchor = anchor - entry_atr
                state['anchor'] = anchor

        # Compute stop and take from anchor
