        # Flat: look for entry signals
        cross_up = macd_line[-2] <= signal_line[-2] and macd_line[-1] > signal_line[-1]
        cross_down = macd_line[-2] >= signal_line[-2] and macd_line[-1] < signal_line[-1]

        long_ok = htf_close[-1] > htf_ema20[-1]
