def strategy(hist, state, pos, ind):
    t = len(hist) - 1

    # Prior 48-bar channel (48 bars BEFORE the current bar)
    hh = ind.highest(hist.high, 48)
    ll = ind.lowest(hist.low, 48)
    prior_high = hh[-2]
    prior_low = ll[-2]

    current_close = hist.close[-1]

