        for k in ("entry_price", "entry_atr", "signal_bar",
                  "last_add_price", "num_adds", "breakeven"):
            if k in state:
                del state[k]

    # --- Manage open long position ---
    if pos > 0:
        entry_price = state.get("entry_price", 0.0)
