                if k in state:
                    del state[k]
            return {"target": 0.0, "stop": None, "take": None}

        # Opposite signal (MACD cross down) -> flatten
        if cross_down:
            for k in ("entry_price", "entry_atr", "signal_bar",
                      "last_add_price", "num_adds", "breakeven"):
