    # Bullish crossover: 5 SMA crosses above 100 SMA
    bullish_cross = (prev_sma5 <= prev_sma100) and (cur_sma5 > cur_sma100)

    # Exit on bearish crossover while long
    if bearish_cross and pos > 0:
        for k in ("entry_price", "entry_atr", "last_add_price", "pyramided"):
            if k in state:
                del state[k]
        return {"target": 0.0, "stop": None, "take": None}

