def strategy(hist, state, pos, ind):
    t = len(hist) - 1

    # Compute ATR
    atr_arr = ind.atr(hist, 14)
    current_atr = atr_arr[-1]

    if np.isnan(current_atr) or current_atr <= 0:
        return {"target": pos, "stop": None, "take": None}

    # Box levels: prior 32 bars (not including current bar)
    box_high = ind.highest(hist.high, 32)[-2]
    box_low = ind.lowest(hist.low, 32)[-2]

    if np.isnan(box_high) or np.isnan(box_low):
        return {"target": pos, "stop": None, "take": None}

    box_height = box_high - box_low

    # 1h EMA filter (last completed 1h candle vs its 20 EMA)
    htf = hist.htf(60)
    long_filter = False
    short_filter = False
    if len(htf) >= 20:
        ema_1h = ind.ema(htf.close, 20)
        if not np.isnan(ema_1h[-1]):
            long_filter = htf.close[-1] > ema_1h[-1]
            short_filter = htf.close[-1] < ema_1h[-1]

    # --- FLAT: look for entries ---
    if pos == 0:
        # Clear residual state from a stop/take fill
        if 'entry_price' in state:
            for k in list(state.keys()):
                del state[k]

        # Long signal: close breaks above box high
        if (hist.close[-1] > box_high and
                box_height <= 6 * current_atr and
                long_filter):
            state['entry_price'] = float(hist.close[-1])
            state['entry_atr'] = float(current_atr)
            state['entry_bar'] = float(t)
            state['direction'] = 1.0
            state['extreme'] = float(hist.high[-1])
            state['initial_stop'] = float(box_low)
            state['breakeven_active'] = 0
            return {"target": 0.75, "stop": float(box_low), "take": None}

        # Short signal: close breaks below box low
        if (hist.close[-1] < box_low and
                box_height <= 6 * current_atr and
                short_filter):
            state['entry_price'] = float(hist.close[-1])
            state['entry_atr'] = float(current_atr)
            state['entry_bar'] = float(t)
            state['direction'] = -1.0
            state['extreme'] = float(hist.low[-1])
            state['initial_stop'] = float(box_high)
            state['breakeven_active'] = 0
            return {"target": -0.75, "stop": float(box_high), "take": None}

        return {"target": 0.0, "stop": None, "take": None}

    # --- IN A TRADE ---
    if 'entry_price' not in state:
        return {"target": 0.0, "stop": None, "take": None}

    direction = state['direction']
    entry_price = state['entry_price']
    entry_atr = state['entry_atr']
    entry_bar = int(state['entry_bar'])
    extreme = state['extreme']
    initial_stop = state['initial_stop']
    breakeven_active = int(state['breakeven_active'])

    # Opposite signal → go flat
    if direction > 0:
        if (hist.close[-1] < box_low and
                box_height <= 6 * current_atr and
                short_filter):
            for k in list(state.keys()):
                del state[k]
            return {"target": 0.0, "stop": None, "take": None}
    else:
        if (hist.close[-1] > box_high and
                box_height <= 6 * current_atr and
                long_filter):
            for k in list(state.keys()):
                del state[k]
            return {"target": 0.0, "stop": None, "take": None}

    # Max holding time: 128 bars
    bars_held = t - entry_bar
    if bars_held >= 128:
        for k in list(state.keys()):
            del state[k]
        return {"target": 0.0, "stop": None, "take": None}

    # Update extreme
    if direction > 0:
        extreme = max(extreme, float(hist.high[-1]))
    else:
        extreme = min(extreme, float(hist.low[-1]))
    state['extreme'] = extreme

    # Check if 2 ATR in profit (evaluated on close, inclusive)
    if direction > 0:
        if hist.close[-1] >= entry_price + 2 * entry_atr:
            breakeven_active = 1
            state['breakeven_active'] = 1
    else:
        if hist.close[-1] <= entry_price - 2 * entry_atr:
            breakeven_active = 1
            state['breakeven_active'] = 1

    # Compute stop level
    if breakeven_active:
        if direction > 0:
            trailing_stop = extreme - 4 * entry_atr
            stop = max(entry_price, trailing_stop)
        else:
            trailing_stop = extreme + 4 * entry_atr
            stop = min(entry_price, trailing_stop)
    else:
        stop = initial_stop

    return {"target": pos, "stop": float(stop), "take": None}

