    prior_20_low = ind.lowest(low, 20)[-2]

    current_close = close[-1]
    current_high = high[-1]
    current_atr = atr[-1]

    # Detect stop-out: we were in a trade but position is now zero
    if state.get("in_trade", False) and pos == 0:
        state["in_trade"] = False
        for k in ("entry_atr", "highest_high", "last_add_price", "pyramided", "current_size"):
            if k in state:
                del state[k]

    # If flat, look for Donchian breakout entry
    if pos == 0 and not state.get("in_trade", False):
        if current_close > prior_20_high:
            # Enter long at 50% equity
            state["in_trade"] = True
            state["entry_atr"] = current_atr
            state["highest_high"] = current_high
            state["last_add_price"] = current_close
            state["pyramided"] = False
            state["current_size"] = 0.5

            stop_level = current_high - 2.0 * current_atr
            return {"target": 0.5, "stop": stop_level, "take": None}

        return {"target": pos, "stop": None, "take": None}

    # If in a long trade
    if state.get("in_trade", False) and pos > 0:
        entry_atr = state["entry_atr"]

        # Update trailing highest high
        if current_high > state["highest_high"]:
            state["highest_high"] = current_high

        highest_high = state["highest_high"]
        stop_level = highest_high - 2.0 * entry_atr

        # Exit signal: close below the prior 20-bar low
        if current_close < prior_20_low:
            state["in_trade"] = False
            for k in ("entry_atr", "highest_high", "last_add_price", "pyramided", "current_size"):
                if k in state:
                    del state[k]
            return {"target": 0.0, "stop": None, "take": None}

        # Pyramiding: add 50% if price moved >= 2*entry_atr above last add price
        if not state["pyramided"] and state["current_size"] < 1.0:
            if current_close >= state["last_add_price"] + 2.0 * entry_atr:
                state["pyramided"] = True
                state["current_size"] = 1.0
                state["last_add_price"] = current_close
                return {"target": 1.0, "stop": stop_level, "take": None}

        # Hold position with trailing stop
        return {"target": pos, "stop": stop_level, "take": None}

    # Default: no change
    return {"target": pos, "stop": None, "take": None}

