        for k in ['entry_price', 'entry_atr', 'last_add_price', 'adds', 'trail_count']:
            if k in state:
                del state[k]

    # Decrement cooldown
    if 'cooldown' in state and state['cooldown'] > 0:
        state['cooldown'] -= 1

    can_enter = state.get('cooldown', 0) == 0

    # Store current position for next bar's transition detection
    state['prev_pos'] = pos

    if pos > 0:
        entry_price = state.get('entry_price', c)
        entry_atr = state.get('entry_atr', 1.0)

        # Bear cross → exit entire position
        if macd_line[-2] >= signal_line[-2] and macd_line[-1] < signal_line[-1]:
            for k in ['entry_price', 'entry_atr', 'last_add_price', 'adds', 'trail_count']:
                if k in state:
                    del state[k]
            return {"target": 0.0, "stop": None, "take": None}

