                adds += 1
                state['adds'] = adds
                state['last_add_price'] = c

        # Trailing: move box up by 2*ATR each time close pushes another 2*ATR in the green
        if c > entry_price and entry_atr > 0:
            potential_trails = int((c - entry_price) / (2 * entry_atr))
        else:
