            state['trail_count'] = potential_trails

        n = state.get('trail_count', 0)
        stop = entry_price + (n - 1) * 2 * entry_atr
        take = entry_price + (n + 1) * 2 * entry_atr

        target = 0.25 * (state.get('adds', 0) + 1)
