            return {"target": 0.75, "stop": None, "take": None}

        # Short entry: bearish cross + 4h close below 50 EMA
        if bearish_cross and h4_close < h4_ema_val:
            state["last_day"] = day
            return {"target": -0.75, "stop": None, "take": None}

    # Hold current position
    return {"target": pos, "stop": None, "take": None}

