def strategy(hist, state, pos, ind):
    t = len(hist) - 1

    # Detect trade end (stop was hit, pos went to 0 while state says we were in a trade)
    if state.get('direction', 0) != 0 and pos == 0:
        state['last_end_bar'] = t
        state['direction'] = 0

    # Compute indicators
    rsi = ind.rsi(hist.close, 7)
    atr_arr = ind.atr(hist, 14)

    curr_atr = atr_arr[-1]
    curr_close = hist.close[-1]

    if np.isnan(curr_atr) or curr_atr <= 0:
        return {"target": pos, "stop": None, "take": None}

    # 4h regime filter
    h4 = hist.htf(240)
    if len(h4) < 51:
        return {"target": pos, "stop": None, "take": None}

    h4_ema50 = ind.ema(h4.close, 50)
    if np.isnan(h4_ema50[-1]):
        return {"target": pos, "stop": None, "take": None}

    h4_bullish = h4.close[-1] > h4_ema50[-1]
    h4_bearish = h4.close[-1] < h4_ema50[-1]

    # RSI cross signals (strict cross events)
    if np.isnan(rsi[-1]) or np.isnan(rsi[-2]):
        return {"target": pos, "stop": None, "take": None}

    long_signal = (rsi[-2] <= 30.0) and (rsi[-1] > 30.0)
    short_signal = (rsi[-2] >= 70.0) and (rsi[-1] < 70.0)

    # Volatility sizing: risk 0.5% of equity per 2 ATR
    size = 0.005 * curr_close / (2.0 * curr_atr)
    size = max(0.05, min(1.0, size))
    size = round(size / 0.05) * 0.05
    size = max(0.05, min(1.0, size))

    # Current position state
    direction = state.get('direction', 0)
    in_long = (pos > 0)
    in_short = (pos < 0)
    flat = (pos == 0)

    # Trailing stop for active position: 2 entry ATR behind extreme
    stop = None
    if pos != 0 and direction != 0:
        entry_bar = int(state.get('entry_bar', t))
        entry_atr = state.get('entry_atr', curr_atr)
        bars_since = t - entry_bar + 1
        if bars_since < 1:
            bars_since = 1

        if direction == 1:
            extreme = ind.highest(hist.high, bars_since)[-1]
            stop = extreme - 2.0 * entry_atr
        else:
            extreme = ind.lowest(hist.low, bars_since)[-1]
            stop = extreme + 2.0 * entry_atr

    # Flip: opposite signal while in a trade (bypasses cooldown and day limit)
    if in_long and short_signal and h4_bearish:
        state['entry_bar'] = t
        state['entry_atr'] = curr_atr
        state['direction'] = -1
        new_stop = hist.low[-1] + 2.0 * curr_atr
        return {"target": -size, "stop": new_stop, "take": None}

    if in_short and long_signal and h4_bullish:
        state['entry_bar'] = t
        state['entry_atr'] = curr_atr
        state['direction'] = 1
        new_stop = hist.high[-1] - 2.0 * curr_atr
        return {"target": size, "stop": new_stop, "take": None}

    # Fresh entry from flat (subject to cooldown and daily limit)
    if flat:
        # Cooldown: 4 hours = 16 bars after trade ends
        cooldown_ok = True
        if 'last_end_bar' in state:
            if t - state['last_end_bar'] < 16:
                cooldown_ok = False

        # Max 1 entry per UTC day
        day_ok = True
        current_day = int(hist.time[-1] // 86400000)
        if 'last_entry_day' in state and state['last_entry_day'] == current_day:
            day_ok = False

        if cooldown_ok and day_ok:
            if long_signal and h4_bullish:
                state['entry_bar'] = t
                state['entry_atr'] = curr_atr
                state['direction'] = 1
                state['last_entry_day'] = current_day
                new_stop = hist.high[-1] - 2.0 * curr_atr
                return {"target": size, "stop": new_stop, "take": None}

            if short_signal and h4_bearish:
                state['entry_bar'] = t
                state['entry_atr'] = curr_atr
                state['direction'] = -1
                state['last_entry_day'] = current_day
                new_stop = hist.low[-1] + 2.0 * curr_atr
                return {"target": -size, "stop": new_stop, "take": None}

    # Hold current position with trailing stop
    if pos != 0:
        return {"target": pos, "stop": stop, "take": None}

    return {"target": 0, "stop": None, "take": None}

