def strategy(hist, state, pos, ind):
    t = len(hist) - 1

    # Compute MACD(8, 17, 9) on 15-min closes
    macd_line, signal_line, _ = ind.macd(hist.close, 8, 17, 9)

    # Guard against NaN
    if np.isnan(macd_line[-1]) or np.isnan(signal_line[-1]):
        return {"target": pos, "stop": None, "take": None}
    if np.isnan(macd_line[-2]) or np.isnan(signal_line[-2]):
        return {"target": pos, "stop": None, "take": None}

    # 1h trend filter: 20 EMA on completed 1h candles
    h1 = hist.htf(60)
    if len(h1) < 21:
        return {"target": pos, "stop": None, "take": None}
    ema20_h1 = ind.ema(h1.close, 20)
    if np.isnan(ema20_h1[-1]):
        return {"target": pos, "stop": None, "take": None}

    h1_bullish = h1.close[-1] > ema20_h1[-1]
    h1_bearish = h1.close[-1] < ema20_h1[-1]

    # MACD cross events (strict cross)
    bullish_cross = (macd_line[-2] <= signal_line[-2]) and (macd_line[-1] > signal_line[-1])
    bearish_cross = (macd_line[-2] >= signal_line[-2]) and (macd_line[-1] < signal_line[-1])

    # Detect transition to flat (stop/take triggered, or our exit order filled)
    if state.get("in_trade", False) and pos == 0:
        state["in_trade"] = False
        state["last_flat_bar"] = t

    # --- Manage open trade ---
    if state.get("in_trade", False):
        direction = int(state["direction"])
        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]
        last_add_price = state["last_add_price"]
        num_adds = int(state["num_adds"])
        breakeven = state.get("breakeven", False)

        # Opposite MACD cross → bail out
        if (direction == 1 and bearish_cross) or (direction == -1 and bullish_cross):
            return {"target": 0, "stop": None, "take": None}

        # Breakeven: once a candle closes at least 2 ATR in the green
        if not breakeven:
            if direction == 1 and hist.close[-1] >= entry_price + 2.0 * entry_atr:
                state["breakeven"] = True
                breakeven = True
            elif direction == -1 and hist.close[-1] <= entry_price - 2.0 * entry_atr:
                state["breakeven"] = True
                breakeven = True

        # Stop level: breakeven if triggered, else 2 ATR initial stop
        if breakeven:
            stop = entry_price
        else:
            stop = entry_price - 2.0 * entry_atr if direction == 1 else entry_price + 2.0 * entry_atr

        # Pyramid: up to 2 adds, each when price moves >= 1 ATR from last add
        if num_adds < 2:
            if direction == 1 and hist.close[-1] >= last_add_price + entry_atr:
                num_adds += 1
                state["num_adds"] = num_adds
                state["last_add_price"] = float(hist.close[-1])
                target = 0.5 + 0.25 * num_adds
                return {"target": target, "stop": stop, "take": None}
            elif direction == -1 and hist.close[-1] <= last_add_price - entry_atr:
                num_adds += 1
                state["num_adds"] = num_adds
                state["last_add_price"] = float(hist.close[-1])
                target = -(0.5 + 0.25 * num_adds)
                return {"target": target, "stop": stop, "take": None}

        # Hold current position size
        target = (0.5 + 0.25 * num_adds) * direction
        return {"target": target, "stop": stop, "take": None}

    # --- Flat: look for new entry ---
    # 48-bar cooldown once flat
    last_flat = state.get("last_flat_bar", -9999)
    if t - last_flat < 48:
        return {"target": 0, "stop": None, "take": None}

    # One and done per UTC day
    current_day = int(hist.time[-1] // 86400000)
    if current_day == int(state.get("last_trade_day", -1)):
        return {"target": 0, "stop": None, "take": None}

    # Entry ATR (14-period)
    atr_val = ind.atr(hist, 14)[-1]
    if np.isnan(atr_val):
        return {"target": 0, "stop": None, "take": None}

    # Long entry: bullish MACD cross + 1h close above 20 EMA
    if bullish_cross and h1_bullish:
        state["in_trade"] = True
        state["direction"] = 1
        state["entry_price"] = float(hist.close[-1])
        state["entry_atr"] = float(atr_val)
        state["last_add_price"] = float(hist.close[-1])
        state["num_adds"] = 0
        state["breakeven"] = False
        state["last_trade_day"] = current_day
        stop = float(hist.close[-1]) - 2.0 * float(atr_val)
        return {"target": 0.5, "stop": stop, "take": None}

    # Short entry: bearish MACD cross + 1h close below 20 EMA
    if bearish_cross and h1_bearish:
        state["in_trade"] = True
        state["direction"] = -1
        state["entry_price"] = float(hist.close[-1])
        state["entry_atr"] = float(atr_val)
        state["last_add_price"] = float(hist.close[-1])
        state["num_adds"] = 0
        state["breakeven"] = False
        state["last_trade_day"] = current_day
        stop = float(hist.close[-1]) + 2.0 * float(atr_val)
        return {"target": -0.5, "stop": stop, "take": None}

    return {"target": 0, "stop": None, "take": None}

