    atr_arr = ind.atr(hist, 14)
    current_atr = atr_arr[-1]

    if np.isnan(current_atr) or current_atr <= 0:
        return {"target": pos, "stop": None, "take": None}

    # 16-bar box: prior 16 bars (indices -17 to -2)
    box_high = float(np.max(hist.high[-17:-1]))
    box_low = float(np.min(hist.low[-17:-1]))
    box_height = box_high - box_low

    # 1h candle above its 20 EMA
    h1 = hist.htf(60)
    h1_ok = False
    if len(h1) >= 20:
        h1_ema20 = ind.ema(h1.close, 20)
        if not np.isnan(h1_ema20[-1]):
            h1_ok = h1.close[-1] > h1_ema20[-1]

    # Clean up state if position was closed by stop/take
    if pos == 0 and state.get("in_trade", False):
        state["in_trade"] = False
        for k in ["entry_price", "entry_atr", "pyramid_count", "last_add_price", "max_ratchet"]:
            if k in state:
                del state[k]

    # Bearish box breakdown (close below prior 16-bar low)
    bearish_breakdown = hist.close[-1] < box_low

    # --- In a trade ---
    if state.get("in_trade", False) and pos > 0:
        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]
        pyramid_count = state.get("pyramid_count", 0)
        last_add_price = state.get("last_add_price", entry_price)
        max_ratchet = state.get("max_ratchet", 0)

        # Bearish breakdown flattens
        if bearish_breakdown:
            state["in_trade"] = False
            for k in ["entry_price", "entry_atr", "pyramid_count", "last_add_price", "max_ratchet"]:
                if k in state:
                    del state[k]
            return {"target": 0.0, "stop": None, "take": None}

        # Pyramiding: up to 2 adds of 0.5, each triggered 1 ATR above last add
        new_target = pos
        if pyramid_count < 2:
            if hist.close[-1] >= last_add_price + entry_atr:
                new_target = min(pos + 0.5, 1.0)
                state["pyramid_count"] = pyramid_count + 1
                state["last_add_price"] = last_add_price + entry_atr

        # Ratchet: for every full ATR of profit on close, shift stop & take forward
        if entry_atr > 0:
            profit_atrs = (hist.close[-1] - entry_price) / entry_atr
            current_ratchet = int(profit_atrs) if profit_atrs >= 1 else 0
        else:
            current_ratchet = 0

        if current_ratchet > max_ratchet:
            max_ratchet = current_ratchet
            state["max_ratchet"] = max_ratchet

        stop = entry_price + (max_ratchet - 2) * entry_atr
        take = entry_price + (max_ratchet + 3) * entry_atr

        return {"target": new_target, "stop": float(stop), "take": float(take)}

    # --- Flat: check entry ---
    if pos == 0:
        if (box_height <= 3.0 * current_atr
                and hist.close[-1] > box_high
                and h1_ok):
            state["in_trade"] = True
            state["entry_price"] = float(hist.close[-1])
            state["entry_atr"] = float(current_atr)
            state["pyramid_count"] = 0
            state["last_add_price"] = float(hist.close[-1])
            state["max_ratchet"] = 0

            stop = float(hist.close[-1] - 2.0 * current_atr)
            take = float(hist.close[-1] + 3.0 * current_atr)
            return {"target": 0.5, "stop": stop, "take": take}

    return {"target": pos, "stop": None, "take": None}

