        if direction == 1:
            profit_atrs = (close - entry_price) / entry_atr
        else:
            profit_atrs = (entry_price - close) / entry_atr

        new_ratchets = int(max(0.0, profit_atrs))
        if new_ratchets > max_ratchets:
            max_ratchets = new_ratchets
            state['max_ratchets'] = max_ratchets

        # Compute stop and take levels
        if direction == 1:
            stop = entry_price + (max_ratchets - 2) * entry_atr
            take = entry_price + (max_ratchets + 2) * entry_atr
        else:
            stop = entry_price - (max_ratchets - 2) * entry_atr
            take = entry_price - (max_ratchets + 2) * entry_atr

        return {"target": pos, "stop": stop, "take": take}

