            size = max(0.05, min(1.0, size))

            state['in_trade'] = True
            state['entry_price'] = close
            state['entry_atr'] = current_atr
            state['direction'] = 1
            state['max_ratchets'] = 0

            stop = close - 2.0 * current_atr
            take = close + 2.0 * current_atr

            return {"target": size, "stop": stop, "take": take}

        elif close < prior_low:
            # Short breakout entry
            size = 0.01 * close / (2.0 * current_atr)
            size = max(0.05, min(1.0, size))
            size = round(size / 0.05) * 0.05
            size = max(0.05, min(1.0, size))

