    if state.get("last_day", -1) != current_day:
        state["last_day"] = current_day
        state["entries_today"] = 0

    if pos > 0:
        # --- In a long trade: manage it ---
        entry_price = state.get("entry_price", current_close)
        entry_atr = state.get("entry_atr", current_atr)
        ratchet_count = int(state.get("ratchet_count", 0))
        breakeven_hit = bool(state.get("breakeven_hit", False))

        # Bearish 20-bar breakdown: exit immediately
        if current_close < prior_20_low:
            for k in ("entry_price", "entry_atr", "ratchet_count", "breakeven_hit"):
                if k in state:
                    del state[k]
            return {"target": 0.0, "stop": None, "take": None}

        # Ratchet: every 2 ATR of profit past entry, shift box up by 2 ATR
        profit = current_close - entry_price
        if profit > 0:
            new_ratchets = int(profit // (2.0 * entry_atr))
            if new_ratchets > ratchet_count:
                ratchet_count = new_ratchets
                state["ratchet_count"] = ratchet_count

        # Breakeven rule: once close >= entry + 1.5 ATR, stop moves to entry permanently
        if current_close >= entry_price + 1.5 * entry_atr:
            if not breakeven_hit:
                breakeven_hit = True
                state["breakeven_hit"] = True

        # Compute stop (tightest applicable)
        stop = entry_price - entry_atr + ratchet_count * 2.0 * entry_atr
        if breakeven_hit:
            stop = max(stop, entry_price)

        # Compute take (nearest applicable)
        take = entry_price + 2.0 * entry_atr + ratchet_count * 2.0 * entry_atr

        return {"target": pos, "stop": stop, "take": take}

    else:
        # --- Flat ---
        # Clean up stale trade state (from a stop/take fill)
        for k in ("entry_price", "entry_atr", "ratchet_count", "breakeven_hit"):
            if k in state:
                del state[k]

        # Donchian breakout entry: close above prior 20-bar high, max 3 entries/day
        if current_close > prior_20_high and state.get("entries_today", 0) < 3:
            state["entries_today"] = int(state.get("entries_today", 0)) + 1
            state["entry_price"] = current_close
            state["entry_atr"] = current_atr
            state["ratchet_count"] = 0
            state["breakeven_hit"] = False

            stop = current_close - current_atr
            take = current_close + 2.0 * current_atr

            return {"target": 0.75, "stop": stop, "take": take}

        return {"target": pos, "stop": None, "take": None}

