    box_high = ind.highest(hist.high, 32)[-2]
    box_low = ind.lowest(hist.low, 32)[-2]
    box_height = box_high - box_low

    # HTF filter: 4H close vs 20 EMA
    htf4 = hist.htf(240)
    if len(htf4) < 21:
        return {"target": pos, "stop": None, "take": None}

    ema20_4h = ind.ema(htf4.close, 20)
    htf_close = htf4.close[-1]
    htf_ema = ema20_4h[-1]

    if np.isnan(htf_ema):
        return {"target": pos, "stop": None, "take": None}

    long_htf = htf_close > htf_ema
    short_htf = htf_close < htf_ema

    # Breakout conditions (level conditions, checked every bar)
    box_ok = box_height <= 6.0 * current_atr
    long_breakout = (hist.close[-1] > box_high) and box_ok and long_htf
    short_breakout = (hist.close[-1] < box_low) and box_ok and short_htf

    if pos == 0:
        # Flat — look for new entry
        if long_breakout:
            state["entry_atr"] = float(current_atr)
            state["entry_price"] = float(hist.close[-1])
            state["extreme"] = float(hist.high[-1])
            state["adds"] = 0
            state["dir"] = 1
            stop = float(hist.close[-1] - 3.0 * current_atr)
            return {"target": 0.5, "stop": stop, "take": None}
        elif short_breakout:
            state["entry_atr"] = float(current_atr)
            state["entry_price"] = float(hist.close[-1])
            state["extreme"] = float(hist.low[-1])
            state["adds"] = 0
            state["dir"] = -1
            stop = float(hist.close[-1] + 3.0 * current_atr)
            return {"target": -0.5, "stop": stop, "take": None}
        else:
            return {"target": 0, "stop": None, "take": None}
    else:
        # In a position — manage it
        direction = int(state.get("dir", 0))
        entry_atr = float(state.get("entry_atr", current_atr))
        entry_price = float(state.get("entry_price", hist.close[-1]))
        adds = int(state.get("adds", 0))
        extreme = float(state.get("extreme", hist.close[-1]))

        if direction == 0:
            return {"target": pos, "stop": None, "take": None}

        # Update extreme with current bar
        if direction == 1:
            extreme = max(extreme, float(hist.high[-1]))
        else:
            extreme = min(extreme, float(hist.low[-1]))
        state["extreme"] = extreme

        # Opposite breakout -> go flat (will re-enter next bar if condition persists)
        if direction == 1 and short_breakout:
            for k in list(state.keys()):
                del state[k]
            return {"target": 0, "stop": None, "take": None}
        elif direction == -1 and long_breakout:
            for k in list(state.keys()):
                del state[k]
            return {"target": 0, "stop": None, "take": None}

        # Scale-in logic: add 0.25 at 2 ATR profit, another 0.25 at 4 ATR profit
        if direction == 1:
            profit = hist.close[-1] - entry_price
        else:
            profit = entry_price - hist.close[-1]

        if profit >= 4.0 * entry_atr:
            desired_adds = 2
        elif profit >= 2.0 * entry_atr:
            desired_adds = 1
        else:
            desired_adds = 0

        if desired_adds > adds:
            state["adds"] = desired_adds
            new_size = min(0.5 + desired_adds * 0.25, 1.0)
            new_target = new_size * direction
            if direction == 1:
                stop = extreme - 3.0 * entry_atr
            else:
                stop = extreme + 3.0 * entry_atr
            return {"target": float(new_target), "stop": float(stop), "take": None}

        # Hold — trail stop 3 entry ATR behind extreme
        if direction == 1:
            stop = extreme - 3.0 * entry_atr
        else:
            stop = extreme + 3.0 * entry_atr

        return {"target": pos, "stop": float(stop), "take": None}

