            state["breakeven_reached"] = True

        if state.get("breakeven_reached", False):
            return {"target": pos, "stop": entry_price, "take": None}

        # No stop yet
        return {"target": pos, "stop": None, "take": None}

    # If flat and not in cooldown, look for entry
    if pos == 0.0 and not in_cooldown:
        prior_highs = hist.high[-17:-1]
