    current_day = int(hist.time[-1] // 86400000)
    if state.get("day", -1) != current_day:
        state["day"] = current_day
        state["entries_today"] = 0

    # --- Manage open long position ---
    if pos > 0:
        # Short signal: bail out at next open
        if short_signal:
            for k in ("entry_price", "entry_atr", "hwm"):
                if k in state:
                    del state[k]
            return {"target": 0.0, "stop": None, "take": None}

        # Update high watermark based on closes
        if close > state.get("hwm", 0.0):
            state["hwm"] = close

        entry_atr = state.get("entry_atr", atr)
        entry_price = state.get("entry_price", close)
        hwm = state.get("hwm", close)

        trail_stop = hwm - 1.5 * entry_atr
        tp_level = entry_price + 4.0 * entry_atr

