    prior_high = ind.highest(hist.high, 16)[-2]
    prior_low = ind.lowest(hist.low, 16)[-2]
    range_height = prior_high - prior_low

    # Cooldown management
    in_cooldown = state.get("in_cooldown", False)
    if in_cooldown:
        if t >= int(state.get("cooldown_end", 0)):
            state["in_cooldown"] = False
            in_cooldown = False

    in_trade = state.get("in_trade", False)

    # Detect stop hit: engine closed position externally
    if in_trade and pos == 0.0:
        state["in_trade"] = False
        state["in_cooldown"] = True
        state["cooldown_end"] = t + 16
        return {"target": 0, "stop": None, "take": None}

    if in_trade:
        direction = int(state.get("direction", 0))
        entry_price = state.get("entry_price", 0.0)
        entry_atr = state.get("entry_atr", 0.0)
        signal_bar = int(state.get("signal_bar", 0))
        pyramided = state.get("pyramided", False)
        stop_price = state.get("stop_price", 0.0)
        last_add_price = state.get("last_add_price", 0.0)

        current_close = hist.close[-1]

        # Opposite signal check (same conditions as entry but reversed)
        opposite_signal = False
        if direction == 1 and current_close < prior_low and range_height <= 6.0 * current_atr:
            opposite_signal = True
        elif direction == -1 and current_close > prior_high and range_height <= 6.0 * current_atr:
            opposite_signal = True

        # Time exit: 256 bars from signal bar
        time_exit = (t - signal_bar) >= 256

        if opposite_signal or time_exit:
            state["in_trade"] = False
            state["in_cooldown"] = True
            state["cooldown_end"] = t + 16
            return {"target": 0, "stop": None, "take": None}

        # Profit check for breakeven stop
        if direction == 1:
            profit = current_close - entry_price
        else:
            profit = entry_price - current_close

        if profit >= 1.5 * entry_atr:
            stop_price = entry_price
            state["stop_price"] = stop_price

        # Pyramid check: add quarter if 2 ATR favorable move from last add
        if not pyramided:
            if direction == 1:
                move = current_close - last_add_price
            else:
                move = last_add_price - current_close

