        return {"target": pos, "stop": stop_price, "take": None}

    # Flat: look for entry signal
    if in_cooldown or pos != 0.0:
        return {"target": pos, "stop": None, "take": None}

    current_close = hist.close[-1]

    # Long breakout: close above prior 16-bar high, range height <= 6 ATR
    if current_close > prior_high and range_height <= 6.0 * current_atr:
        state["in_trade"] = True
        state["direction"] = 1
        state["entry_price"] = current_close
        state["entry_atr"] = current_atr
        state["signal_bar"] = t
        state["pyramided"] = False
        state["stop_price"] = prior_low
        state["last_add_price"] = current_close
        return {"target": 0.25, "stop": prior_low, "take": None}

    # Short breakout: close below prior 16-bar low, range height <= 6 ATR
    if current_close < prior_low and range_height <= 6.0 * current_atr:
        state["in_trade"] = True
        state["direction"] = -1
        state["entry_price"] = current_close
        state["entry_atr"] = current_atr
        state["signal_bar"] = t
        state["pyramided"] = False
        state["stop_price"] = prior_high
        state["last_add_price"] = current_close
        return {"target": -0.25, "stop": prior_high, "take": None}

    return {"target": pos, "stop": None, "take": None}

