def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close[-1]

    if t < 97:
        return {"target": 0.0, "stop": None, "take": None}

    prior_high_96 = ind.highest(hist.high, 96)[-2]
    prior_low_96 = ind.lowest(hist.low, 96)[-2]
    current_atr = ind.atr(hist, 14)[-1]
    current_day = int(hist.time[-1] // 86400000)

    bullish_breakout = close > prior_high_96
    bearish_breakout = close < prior_low_96

    # Initialize state
    if 'init' not in state:
        state['init'] = True
        state['setup_dir'] = 0
        state['setup_level'] = 0.0
        state['setup_bar'] = 0
        state['entry_price'] = 0.0
        state['entry_atr'] = 0.0
        state['last_add_price'] = 0.0
        state['num_adds'] = 0
        state['trade_day'] = -1
        state['in_trade'] = False

    # Detect external close (TP filled by engine)
    if state['in_trade'] and pos == 0:
        state['in_trade'] = False

    # Opposite breakout signal closes the open position
    if state['in_trade'] and pos != 0:
        direction = 1 if pos > 0 else -1
        if (direction > 0 and bearish_breakout) or (direction < 0 and bullish_breakout):
            state['in_trade'] = False
            if bearish_breakout:
                state['setup_dir'] = -1
                state['setup_level'] = prior_low_96
                state['setup_bar'] = t
            else:
                state['setup_dir'] = 1
                state['setup_level'] = prior_high_96
                state['setup_bar'] = t
            return {"target": 0.0, "stop": None, "take": None}

    # New breakouts overwrite old setups
    if bullish_breakout:
        state['setup_dir'] = 1
        state['setup_level'] = prior_high_96
        state['setup_bar'] = t
    if bearish_breakout:
        state['setup_dir'] = -1
        state['setup_level'] = prior_low_96
        state['setup_bar'] = t

    # Manage open trade: pyramiding and take-profit
    if state['in_trade'] and pos != 0:
        direction = 1 if pos > 0 else -1
        entry_price = state['entry_price']
        entry_atr = state['entry_atr']

        if direction > 0:
            take_level = entry_price + 4.0 * entry_atr
        else:
            take_level = entry_price - 4.0 * entry_atr

        last_add = state['last_add_price']
        num_adds = state['num_adds']
        cur_size = abs(pos)

        # Pyramid: add 50% when price moves >= 1 ATR from last add, cap at 100%
        if num_adds < 2 and cur_size < 0.99:
            if direction > 0 and close >= last_add + entry_atr:
                new_size = min(cur_size + 0.5, 1.0)
                state['last_add_price'] = close
                state['num_adds'] = num_adds + 1
                return {"target": new_size, "stop": None, "take": take_level}
            elif direction < 0 and close <= last_add - entry_atr:
                new_size = min(cur_size + 0.5, 1.0)
                state['last_add_price'] = close
                state['num_adds'] = num_adds + 1
                return {"target": -new_size, "stop": None, "take": take_level}

        return {"target": pos, "stop": None, "take": take_level}

    # Entry logic when flat
    if pos == 0 and state['setup_dir'] != 0:
        setup_dir = state['setup_dir']
        setup_level = state['setup_level']
        setup_bar = state['setup_bar']

        # Setup expires after 16 bars
        if t - setup_bar >= 16:
            state['setup_dir'] = 0
            return {"target": 0.0, "stop": None, "take": None}

        # Max one entry per day
        if state['trade_day'] == current_day:
            return {"target": 0.0, "stop": None, "take": None}

        # Retest trigger
        triggered = False
        if setup_dir > 0 and hist.low[-1] <= setup_level:
            triggered = True
        elif setup_dir < 0 and hist.high[-1] >= setup_level:
            triggered = True

        if triggered:
            state['in_trade'] = True
            state['entry_price'] = close
            state['entry_atr'] = current_atr
            state['last_add_price'] = close
            state['num_adds'] = 0
            state['trade_day'] = current_day
            state['setup_dir'] = 0

            if setup_dir > 0:
                take_level = close + 4.0 * current_atr
            else:
                take_level = close - 4.0 * current_atr

            return {"target": 0.5 * setup_dir, "stop": None, "take": take_level}

    return {"target": pos, "stop": None, "take": None}

