    prev_rsi = rsi[-2]
    current_atr = atr_arr[-1]
    current_close = close[-1]

    # Signals: cross back up through 20 / cross back down through 80
    long_signal = (prev_rsi <= 20) and (current_rsi > 20)
    short_signal = (prev_rsi >= 80) and (current_rsi < 80)

    # If position was stopped out between bars, clear trade state
    if pos == 0 and state.get('direction', 0) != 0:
        state['direction'] = 0

    trade_dir = state.get('direction', 0)

    # --- Flat: look for entries ---
    if pos == 0:
        if long_signal:
            size = 0.01 * current_close / (2.0 * current_atr)
            size = max(0.05, min(1.0, size))
            state['entry_price'] = current_close
            state['entry_atr'] = current_atr
            state['direction'] = 1
            state['scaled'] = False
            return {"target": size, "stop": current_close - current_atr, "take": None}
        elif short_signal:
            size = 0.01 * current_close / (2.0 * current_atr)
            size = max(0.05, min(1.0, size))
            state['entry_price'] = current_close
            state['entry_atr'] = current_atr
            state['direction'] = -1
            state['scaled'] = False
            return {"target": -size, "stop": current_close + current_atr, "take": None}
        else:
            return {"target": 0, "stop": None, "take": None}

    # --- In a position ---
    entry_price = state['entry_price']
    entry_atr = state['entry_atr']
    scaled = state.get('scaled', False)

    # Opposite signal -> bail and flip
    if (trade_dir == 1 and short_signal) or (trade_dir == -1 and long_signal):
        if short_signal:
            size = 0.01 * current_close / (2.0 * current_atr)
            size = max(0.05, min(1.0, size))
            state['entry_price'] = current_close
            state['entry_atr'] = current_atr
            state['direction'] = -1
            state['scaled'] = False
            return {"target": -size, "stop": current_close + current_atr, "take": None}
        else:
            size = 0.01 * current_close / (2.0 * current_atr)
            size = max(0.05, min(1.0, size))
            state['entry_price'] = current_close
            state['entry_atr'] = current_atr
            state['direction'] = 1
            state['scaled'] = False
            return {"target": size, "stop": current_close - current_atr, "take": None}

    # Compute stop for current trade
    if trade_dir == 1:
        stop = entry_price - entry_atr
    else:
        stop = entry_price + entry_atr

    # Scale-out check: first time close is at least 2 ATR in profit
    if not scaled:
        if trade_dir == 1:
            if current_close - entry_price >= 2.0 * entry_atr:
                state['scaled'] = True
                return {"target": pos / 2.0, "stop": stop, "take": None}
        else:
            if entry_price - current_close >= 2.0 * entry_atr:
                state['scaled'] = True
                return {"target": pos / 2.0, "stop": stop, "take": None}

    # Hold position with stop
    return {"target": pos, "stop": stop, "take": None}

