def strategy(hist, state, pos, ind):
    t = len(hist) - 1

    # ATR(14) on 15m
    atr_arr = ind.atr(hist, 14)
    current_atr = atr_arr[-1]
    if np.isnan(current_atr) or current_atr <= 0:
        return {"target": pos, "stop": None, "take": None}

    # 4H trend filter: 50 EMA on 4H close
    htf4 = hist.htf(240)
    if len(htf4) < 51:
        return {"target": pos, "stop": None, "take": None}
    ema50_4h = ind.ema(htf4.close, 50)
    if np.isnan(ema50_4h[-1]):
        return {"target": pos, "stop": None, "take": None}

    trend_up = htf4.close[-1] > ema50_4h[-1]
    trend_down = htf4.close[-1] < ema50_4h[-1]

    # Box: highest high and lowest low of the 16 bars BEFORE current
    box_high = float(np.max(hist.high[-17:-1]))
    box_low = float(np.min(hist.low[-17:-1]))
    box_height = box_high - box_low
    box_valid = box_height <= 3.0 * current_atr

    # Daily trade counter (UTC)
    current_day = int(hist.time[-1] // 86400000)
    if state.get('day', -1) != current_day:
        state['day'] = current_day
        state['trades_today'] = 0

    close = float(hist.close[-1])

    # --- Manage existing position ---
    if pos != 0:
        entry_bar = int(state.get('entry_bar', 0))
        entry_price = state.get('entry_price', 0.0)
        entry_atr = state.get('entry_atr', 0.0)
        direction = 1 if pos > 0 else -1

        # Time stop: 128 bars since signal bar
        if t - entry_bar >= 128:
            return {"target": 0, "stop": None, "take": None}

        # Opposite signal closes the trade
        if direction == 1 and box_valid and trend_down and close < box_low:
            return {"target": 0, "stop": None, "take": None}
        if direction == -1 and box_valid and trend_up and close > box_high:
            return {"target": 0, "stop": None, "take": None}

        # Keep position alive with TP
        if direction == 1:
            take = entry_price + 2.0 * entry_atr
        else:
            take = entry_price - 2.0 * entry_atr
        return {"target": pos, "stop": None, "take": take}

    # --- Flat: look for new entry ---
    if not box_valid:
        return {"target": 0, "stop": None, "take": None}

    if state.get('trades_today', 0) >= 3:
        return {"target": 0, "stop": None, "take": None}

    # Long breakout
    if close > box_high and trend_up:
        state['entry_bar'] = t
        state['entry_price'] = close
        state['entry_atr'] = float(current_atr)
        state['trades_today'] = state.get('trades_today', 0) + 1
        take = close + 2.0 * float(current_atr)
        return {"target": 1.0, "stop": None, "take": take}

    # Short breakout
    if close < box_low and trend_down:
        state['entry_bar'] = t
        state['entry_price'] = close
        state['entry_atr'] = float(current_atr)
        state['trades_today'] = state.get('trades_today', 0) + 1
        take = close - 2.0 * float(current_atr)
        return {"target": -1.0, "stop": None, "take": take}

    return {"target": 0, "stop": None, "take": None}

