def strategy(hist, state, pos, ind):
    t = len(hist) - 1

    close = hist.close
    high = hist.high
    low = hist.low

    cur_high = high[-1]
    cur_low = low[-1]
    cur_close = close[-1]

    # ATR(14)
    atr_arr = ind.atr(hist, 14)
    cur_atr = atr_arr[-1]

    # Prior 96-bar high/low (the 96 bars BEFORE the current bar)
    prior_96_high = ind.highest(high, 96)[-2]
    prior_96_low = ind.lowest(low, 96)[-2]

    # 1h completed candle vs its 20 EMA
    h1 = hist.htf(60)
    if len(h1) >= 20:
        h1_ema20 = ind.ema(h1.close, 20)[-1]
        h1_above_ema = h1.close[-1] > h1_ema20
        h1_below_ema = h1.close[-1] < h1_ema20
    else:
        h1_above_ema = False
        h1_below_ema = False

    # --- Breakout detection: arm setups ---
    if cur_high > prior_96_high:
        state['long_armed'] = True
        state['long_level'] = float(prior_96_high)
        state['long_arm_bar'] = t

    if cur_low < prior_96_low:
        state['short_armed'] = True
        state['short_level'] = float(prior_96_low)
        state['short_arm_bar'] = t

    # Expire setups after 64 bars
    if state.get('long_armed', False) and (t - state.get('long_arm_bar', 0)) >= 64:
        state['long_armed'] = False
    if state.get('short_armed', False) and (t - state.get('short_arm_bar', 0)) >= 64:
        state['short_armed'] = False

    # --- Entry signals ---
    long_signal = False
    short_signal = False

    if state.get('long_armed', False):
        if cur_low <= state.get('long_level', 0.0) and h1_above_ema:
            long_signal = True

    if state.get('short_armed', False):
        if cur_high >= state.get('short_level', 0.0) and h1_below_ema:
            short_signal = True

    # --- Opposite signal closes the position ---
    if pos > 0 and short_signal:
        return {"target": 0.0, "stop": None, "take": None}
    if pos < 0 and long_signal:
        return {"target": 0.0, "stop": None, "take": None}

    # --- Entry when flat ---
    if pos == 0:
        if long_signal:
            state['entry_price'] = float(cur_close)
            state['entry_atr'] = float(cur_atr)
            state['trade_dir'] = 1
            state['scaled_out'] = False
            state['extreme'] = float(cur_high)
            return {"target": 1.0, "stop": None, "take": None}

        if short_signal:
            state['entry_price'] = float(cur_close)
            state['entry_atr'] = float(cur_atr)
            state['trade_dir'] = -1
            state['scaled_out'] = False
            state['extreme'] = float(cur_low)
            return {"target": -1.0, "stop": None, "take": None}

    # --- Position management ---
    if pos != 0:
        entry_price = state.get('entry_price', cur_close)
        entry_atr = state.get('entry_atr', cur_atr)
        trade_dir = state.get('trade_dir', 1 if pos > 0 else -1)
        scaled_out = state.get('scaled_out', False)

        if trade_dir == 1:
            # Update extreme (highest high since entry)
            if cur_high > state.get('extreme', cur_high):
                state['extreme'] = float(cur_high)
            extreme = state.get('extreme', cur_high)

            if not scaled_out:
                # Scale out half once close >= entry + 3 ATR
                if cur_close >= entry_price + 3.0 * entry_atr:
                    state['scaled_out'] = True
                    trail_stop = extreme - 4.0 * entry_atr
                    return {"target": 0.5, "stop": trail_stop, "take": None}
            else:
                # Trailing stop 4 ATR behind the extreme
                trail_stop = extreme - 4.0 * entry_atr
                return {"target": pos, "stop": trail_stop, "take": None}

        elif trade_dir == -1:
            # Update extreme (lowest low since entry)
            if cur_low < state.get('extreme', cur_low):
                state['extreme'] = float(cur_low)
            extreme = state.get('extreme', cur_low)

            if not scaled_out:
                # Scale out half once close <= entry - 3 ATR
                if cur_close <= entry_price - 3.0 * entry_atr:
                    state['scaled_out'] = True
                    trail_stop = extreme + 4.0 * entry_atr
                    return {"target": -0.5, "stop": trail_stop, "take": None}
            else:
                # Trailing stop 4 ATR behind the extreme
                trail_stop = extreme + 4.0 * entry_atr
                return {"target": pos, "stop": trail_stop, "take": None}

    return {"target": pos, "stop": None, "take": None}

