    # Compute indicators
    ema20 = ind.ema(hist.close, 20)
    ema50 = ind.ema(hist.close, 50)
    atr = ind.atr(hist, 14)

    # Cross signals (strict cross events)
    long_cross = (ema20[-2] <= ema50[-2]) and (ema20[-1] > ema50[-1])
    short_cross = (ema20[-2] >= ema50[-2]) and (ema20[-1] < ema50[-1])

    # Current UTC day from bar open time
    day_num = int(hist.time[-1] // 86400000)

    # --- In-trade management ---
    if state.get("in_trade", False):
        # Position was closed by stop during this bar
        if pos == 0.0:
            state["in_trade"] = False
            return {"target": 0.0, "stop": None, "take": None}

        direction = int(state["direction"])
        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]
        signal_bar = int(state["signal_bar"])
        breakeven = state.get("breakeven", False)

        # Exit on opposite signal
        if (direction == 1 and short_cross) or (direction == -1 and long_cross):
            state["in_trade"] = False
            return {"target": 0.0, "stop": None, "take": None}

        # Exit after 32 bars since signal
        if t - signal_bar >= 32:
            state["in_trade"] = False
            return {"target": 0.0, "stop": None, "take": None}

        # Check breakeven ratchet (evaluated on bar close, inclusive)
        if not breakeven:
            if direction == 1:
                profit = hist.close[-1] - entry_price
            else:
                profit = entry_price - hist.close[-1]
            if profit >= 1.5 * entry_atr:
                breakeven = True
                state["breakeven"] = True

        # Stop at breakeven once ratcheted, otherwise no stop
        stop = entry_price if breakeven else None

        return {"target": pos, "stop": stop, "take": None}

    # --- Flat: look for entry ---
    if long_cross or short_cross:
        # Daily entry limit (max 3 per UTC day)
        if state.get("day_key", -1) == day_num:
            entries_today = int(state.get("entries_today", 0))
        else:
            entries_today = 0

        if entries_today >= 3:
            return {"target": pos, "stop": None, "take": None}

        # Determine direction
        direction = 1 if long_cross else -1

        # Record trade state
        state["in_trade"] = True
        state["direction"] = direction
        state["entry_price"] = float(hist.close[-1])
        state["entry_atr"] = float(atr[-1])
        state["signal_bar"] = t
        state["breakeven"] = False
        state["day_key"] = day_num
        state["entries_today"] = entries_today + 1

        return {"target": float(direction), "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

