    close = hist.close[-1]
    low = hist.low[-1]
    high = hist.high[-1]

    # ATR
    atr_val = ind.atr(hist, 14)[-1]

    # Breakout conditions (level conditions checked every bar)
    long_breakout = close > prior_48_high
    short_breakout = close < prior_48_low

    # Arm setups on breakout
    if long_breakout:
        state['armed_long'] = 1
        state['arm_bar_long'] = t
        state['breakout_level_long'] = prior_48_high

    if short_breakout:
        state['armed_short'] = 1
        state['arm_bar_short'] = t
        state['breakout_level_short'] = prior_48_low

    # Expire armed setups after 8 bars
    if state.get('armed_long', 0) == 1:
        if t - state.get('arm_bar_long', 0) > 8:
            state['armed_long'] = 0
    if state.get('armed_short', 0) == 1:
        if t - state.get('arm_bar_short', 0) > 8:
            state['armed_short'] = 0

    # --- Position management ---
    if pos != 0:
        entry_price = state.get('entry_price', close)
        entry_atr = state.get('entry_atr', atr_val)
        scaled = state.get('scaled_out', 0)

        # Opposite signal closes the trade
        if pos > 0 and short_breakout:
            state['scaled_out'] = 0
            return {"target": 0.0, "stop": None, "take": None}
        if pos < 0 and long_breakout:
            state['scaled_out'] = 0
            return {"target": 0.0, "stop": None, "take": None}

        # Profit check (bar close, inclusive)
        if pos > 0:
            profit = close - entry_price
        else:
            profit = entry_price - close

        if profit >= 2 * entry_atr and scaled == 0:
            # Scale out: cut position in half, stop to breakeven
            state['scaled_out'] = 1
            new_target = pos * 0.5
            new_target = round(new_target / 0.05) * 0.05
            return {"target": new_target, "stop": entry_price, "take": None}

        if scaled == 1:
            # Let the rest ride with breakeven stop
            return {"target": pos, "stop": entry_price, "take": None}

        # Before 2 ATR profit: no stop, no take
        return {"target": pos, "stop": None, "take": None}

    # --- Flat: look for entries ---
    # Long entry
    if state.get('armed_long', 0) == 1:
        arm_bar = state.get('arm_bar_long', 0)
        if 0 < t - arm_bar <= 8:
            breakout_level = state.get('breakout_level_long', 0.0)
            if low <= breakout_level and h4_bullish:
                state['entry_price'] = close
                state['entry_atr'] = atr_val
                state['scaled_out'] = 0
                state['armed_long'] = 0
                return {"target": 1.0, "stop": None, "take": None}

    # Short entry
    if state.get('armed_short', 0) == 1:
        arm_bar = state.get('arm_bar_short', 0)
        if 0 < t - arm_bar <= 8:
            breakout_level = state.get('breakout_level_short', 0.0)
            if high >= breakout_level and h4_bearish:
                state['entry_price'] = close
                state['entry_atr'] = atr_val
                state['scaled_out'] = 0
                state['armed_short'] = 0
                return {"target": -1.0, "stop": None, "take": None}

    return {"target": pos, "stop": None, "take": None}

