        for k in ["direction", "entry_price", "entry_atr", "added", "breakeven"]:
            if k in state:
                del state[k]
        return {"target": 0.0, "stop": None, "take": None}

    # Cooldown: no new entries for 4 bars after trade ends
    if t < state.get("cooldown_until", 0):
        return {"target": pos, "stop": None, "take": None}

    # Flat: look for entries
    if pos == 0.0:
        if long_signal:
            entry_price = hist.close[-1]
            state["in_trade"] = True
            state["direction"] = 1
            state["entry_price"] = entry_price
            state["entry_atr"] = atr_now
            state["added"] = False
            state["breakeven"] = False
            stop = entry_price - 1.5 * atr_now
            return {"target": 0.5, "stop": stop, "take": None}
        elif short_signal:
            entry_price = hist.close[-1]
            state["in_trade"] = True
            state["direction"] = -1
            state["entry_price"] = entry_price
            state["entry_atr"] = atr_now
            state["added"] = False
            state["breakeven"] = False
            stop = entry_price + 1.5 * atr_now
            return {"target": -0.5, "stop": stop, "take": None}
        return {"target": 0.0, "stop": None, "take": None}

    # In a trade
    direction = state.get("direction", 0)
    entry_price = state.get("entry_price", 0.0)
    entry_atr = state.get("entry_atr", 0.0)
    added = state.get("added", False)
    breakeven = state.get("breakeven", False)

    # Opposite signal exits the trade
    if (direction == 1 and short_signal) or (direction == -1 and long_signal):
        return {"target": 0.0, "stop": None, "take": None}

    # Check if price hit 2 ATR in profit on close → move stop to breakeven
    if not breakeven:
        if direction == 1 and hist.close[-1] >= entry_price + 2.0 * entry_atr:
            state["breakeven"] = True
            breakeven = True
        elif direction == -1 and hist.close[-1] <= entry_price - 2.0 * entry_atr:
            state["breakeven"] = True
            breakeven = True

    # Pyramid: add 0.5 once when 2 ATR in favour from entry
    if not added:
        if direction == 1 and hist.close[-1] >= entry_price + 2.0 * entry_atr:
            state["added"] = True
            stop = entry_price if breakeven else entry_price - 1.5 * entry_atr
            return {"target": 1.0, "stop": stop, "take": None}
        elif direction == -1 and hist.close[-1] <= entry_price - 2.0 * entry_atr:
            state["added"] = True
            stop = entry_price if breakeven else entry_price + 1.5 * entry_atr
            return {"target": -1.0, "stop": stop, "take": None}

    # Normal bar: maintain position with appropriate stop
    if breakeven:
        stop = entry_price
    else:
        if direction == 1:
            stop = entry_price - 1.5 * entry_atr
        else:
            stop = entry_price + 1.5 * entry_atr

    return {"target": pos, "stop": stop, "take": None}

