            if k in state:
                del state[k]

    # --- Manage existing position ---
    if pos != 0:
        direction = 1 if pos > 0 else -1
        entry_price = state.get("entry_price", close)
        entry_atr = state.get("entry_atr", atr)

        # Opposite signal closes the position (no reversal)
        if (direction == 1 and short_signal) or (direction == -1 and long_signal):
            for k in ("entry_price", "entry_atr", "be_triggered", "extreme", "stop_level"):
                if k in state:
                    del state[k]
            return {"target": 0.0, "stop": None, "take": None}

        # Breakeven trigger: close at least 2 ATR in the green
        if not state.get("be_triggered", False):
            if direction == 1 and close >= entry_price + 2 * entry_atr:
                state["be_triggered"] = True
                state["extreme"] = close
                state["stop_level"] = entry_price
            elif direction == -1 and close <= entry_price - 2 * entry_atr:
                state["be_triggered"] = True
                state["extreme"] = close
                state["stop_level"] = entry_price

        # Compute stop level
        if state.get("be_triggered", False):
            if direction == 1:
                if close > state.get("extreme", close):
                    state["extreme"] = close
                trail = state["extreme"] - 2 * entry_atr
                state["stop_level"] = max(state.get("stop_level", entry_price), trail)
            else:
                if close < state.get("extreme", close):
                    state["extreme"] = close
                trail = state["extreme"] + 2 * entry_atr
                state["stop_level"] = min(state.get("stop_level", entry_price), trail)
