        if entry_atr > 0:
            profit_atrs = int((highest_close - entry_price) / entry_atr)
        else:
            profit_atrs = 0
        stop_level = entry_price + (profit_atrs - 1) * entry_atr

        # Scale out: bank half when close >= entry + 2 ATR
        if not state.get("scaled", False) and close >= entry_price + 2 * entry_atr:
            state["scaled"] = True
            half_pos = pos / 2.0
            new_target = round(half_pos / 0.05) * 0.05
            new_target = max(new_target, 0.05)
            return {"target": new_target, "stop": stop_level, "take": None}

        return {"target": pos, "stop": stop_level, "take": None}

    # Not in a trade – if somehow holding a position, flatten
    if pos != 0:
        return {"target": 0.0, "stop": None, "take": None}

    # --- Entry logic (only when flat) ---
    if t < 17:
        return {"target": 0.0, "stop": None, "take": None}

    if np.isnan(atr) or atr <= 0:
        return {"target": 0.0, "stop": None, "take": None}

    # 4h trend filter: last completed 4h close above its 20 EMA
    h4 = hist.htf(240)
    if len(h4) < 20:
        return {"target": 0.0, "stop": None, "take": None}
    h4_ema = ind.ema(h4.close, 20)
    if np.isnan(h4_ema[-1]) or h4.close[-1] <= h4_ema[-1]:
        return {"target": 0.0, "stop": None, "take": None}

    # Max 2 entries per UTC day
    if state.get("entries_today", 0) >= 2:
        return {"target": 0.0, "stop": None, "take": None}

    # 16-bar box: the prior 16 bars (indices -17 through -2)
    box_high = float(np.max(hist.high[-17:-1]))
    box_low = float(np.min(hist.low[-17:-1]))
    box_height = box_high - box_low

    # Box height must be at most 3 ATRs
    if box_height > 3 * atr:
        return {"target": 0.0, "stop": None, "take": None}

    # Breakout: close strictly above box high (level condition)
    if close <= box_high:
        return {"target": 0.0, "stop": None, "take": None}

    # --- Enter long ---
    # Sizing: risk 1% of equity per 2 ATR
    frac = 0.01 * close / (2 * atr)
    frac = min(frac, 1.0)
    frac = max(frac, 0.05)
    frac = round(frac / 0.05) * 0.05

    # Store trade state
    state["in_trade"] = True
    state["entry_price"] = close
    state["entry_atr"] = atr
    state["box_high"] = box_high
    state["box_low"] = box_low
    state["highest_close"] = close
    state["scaled"] = False
    state["entries_today"] = state.get("entries_today", 0) + 1

    # Hard stop: 1 ATR below entry price
    stop_level = close - atr

    return {"target": frac, "stop": stop_level, "take": None}

