    # Current bar close
    c = hist.close[-1]

    # Donchian breakout signals (level conditions, checked every bar)
    long_signal = c > prior_high
    short_signal = c < prior_low

    # ATR for profit measurement
    atr_val = ind.atr(hist, 14)[-1]

    in_trade = state.get("in_trade", 0)

    # --- FLAT: look for entries ---
    if in_trade == 0:
        if long_signal and long_filter:
            state["in_trade"] = 1
            state["direction"] = 1
            state["entry_price"] = c
            state["entry_atr"] = atr_val
            state["scaled_out"] = 0
            return {"target": 1.0, "stop": None, "take": None}
        elif short_signal and short_filter:
            state["in_trade"] = 1
            state["direction"] = -1
            state["entry_price"] = c
            state["entry_atr"] = atr_val
            state["scaled_out"] = 0
            return {"target": -1.0, "stop": None, "take": None}
        return {"target": 0.0, "stop": None, "take": None}

    # --- IN A TRADE ---
    direction = state["direction"]
    entry_price = state["entry_price"]
