                return {"target": 0.5 * direction, "stop": entry_price, "take": None}

        # Already scaled out: maintain breakeven stop on remaining position
        if scaled_out:
            return {"target": pos, "stop": entry_price, "take": None}

        # In trade, no exit condition met yet
        return {"target": pos, "stop": None, "take": None}

