def strategy(hist, state, pos, ind):
    t = len(hist) - 1
    close = hist.close[-1]

    # Compute indicators
    rsi = ind.rsi(hist.close, 14)
    current_rsi = rsi[-1]
    prev_rsi = rsi[-2]

    atr_arr = ind.atr(hist, 14)
    current_atr = atr_arr[-1]

    # Determine UTC day and reset daily entry counter
    current_time = hist.time[-1]
    current_day = int(current_time // 86400000)

    if state.get('last_day', -1) != current_day:
        state['last_day'] = current_day
        state['entries_today'] = 0

    # Signals: cross events
    long_signal = (prev_rsi <= 20.0) and (current_rsi > 20.0)
    short_signal = (prev_rsi >= 80.0) and (current_rsi < 80.0)

    # --- In a trade ---
    if pos != 0:
        direction = 1 if pos > 0 else -1

        # Opposite signal flips flat
        if (direction == 1 and short_signal) or (direction == -1 and long_signal):
            for k in ('entry_bar', 'entry_price', 'entry_atr', 'current_stop',
                      'current_take', 'adds_done', 'last_add_price', 'direction'):
                if k in state:
                    del state[k]
            return {"target": 0.0, "stop": None, "take": None}

        # Time stop: exit at open after 64 bars
        entry_bar = int(state.get('entry_bar', t))
        if t - entry_bar >= 64:
            for k in ('entry_bar', 'entry_price', 'entry_atr', 'current_stop',
                      'current_take', 'adds_done', 'last_add_price', 'direction'):
                if k in state:
                    del state[k]
            return {"target": 0.0, "stop": None, "take": None}

        # Retrieve trade parameters
        entry_atr = state['entry_atr']
        current_stop = state['current_stop']
        current_take = state['current_take']

        # Ratchet: move box 2 ATR forward each time close clears another 2 ATR
        if direction == 1:
            while close >= current_take:
                current_stop += 2.0 * entry_atr
                current_take += 2.0 * entry_atr
        else:
            while close <= current_take:
                current_stop -= 2.0 * entry_atr
                current_take -= 2.0 * entry_atr

        state['current_stop'] = current_stop
        state['current_take'] = current_take

        # Pyramid adds: up to 2 adds of half size, 1 entry ATR past last add
        adds_done = int(state.get('adds_done', 0))
        if adds_done < 2:
            last_add_price = state['last_add_price']
            if direction == 1:
                if close >= last_add_price + entry_atr:
                    new_pos = min(pos + 0.5, 1.0)
                    if new_pos > pos:
                        state['adds_done'] = adds_done + 1
                        state['last_add_price'] = close
                        return {"target": new_pos, "stop": current_stop, "take": current_take}
            else:
                if close <= last_add_price - entry_atr:
                    new_pos = max(pos - 0.5, -1.0)
                    if new_pos < pos:
                        state['adds_done'] = adds_done + 1
                        state['last_add_price'] = close
                        return {"target": new_pos, "stop": current_stop, "take": current_take}

        # Hold position, maintain stop/take
        return {"target": pos, "stop": current_stop, "take": current_take}

    # --- Flat: look for entries ---
    if long_signal or short_signal:
        # Max 3 entries per UTC day
        if state.get('entries_today', 0) >= 3:
            return {"target": 0.0, "stop": None, "take": None}

        # Guard against invalid ATR
        if np.isnan(current_atr) or current_atr <= 0:
            return {"target": 0.0, "stop": None, "take": None}

        direction = 1 if long_signal else -1
        entry_price = close
        entry_atr = current_atr

        if direction == 1:
            stop = entry_price - 2.0 * entry_atr
            take = entry_price + 2.0 * entry_atr
        else:
            stop = entry_price + 2.0 * entry_atr
            take = entry_price - 2.0 * entry_atr

        # Store trade state
        state['entry_bar'] = t
        state['entry_price'] = entry_price
        state['entry_atr'] = entry_atr
        state['current_stop'] = stop
        state['current_take'] = take
        state['adds_done'] = 0
        state['last_add_price'] = entry_price
        state['direction'] = direction
        state['entries_today'] = state.get('entries_today', 0) + 1

        target = 0.5 * direction
        return {"target": target, "stop": stop, "take": take}

    # No signal, remain flat
    return {"target": 0.0, "stop": None, "take": None}

