    if pos > 0:
        direction = 1
    elif pos < 0:
        direction = -1
    else:
        direction = 0

    # --- In a position ---
    if direction != 0:
        entry_price = state.get("entry_price", 0.0)
        entry_atr = state.get("entry_atr", 1.0)
        scaled_out = state.get("scaled_out", 0)

        # Opposite signal closes the trade
        if (direction == 1 and short_signal) or (direction == -1 and long_signal):
            state["cooldown_until"] = t + 5
            if "entry_price" in state:
                del state["entry_price"]
            if "entry_atr" in state:
                del state["entry_atr"]
            if "scaled_out" in state:
                del state["scaled_out"]
            return {"target": 0.0, "stop": None, "take": None}

        # Scale out to half size once profit >= 1.5 * entry ATR
        if scaled_out == 0:
            if direction == 1:
                profit = hist.close[-1] - entry_price
            else:
                profit = entry_price - hist.close[-1]

            if profit >= 1.5 * entry_atr:
                half_pos = round((pos / 2.0) / 0.05) * 0.05
                state["scaled_out"] = 1
                return {"target": half_pos, "stop": None, "take": None}

        # Hold position
        return {"target": pos, "stop": None, "take": None}

    # --- Flat: check cooldown then look for entry ---
    cooldown_until = state.get("cooldown_until", 0)
    if t < cooldown_until:
        return {"target": 0.0, "stop": None, "take": None}

    # Guard against invalid ATR
    if not (current_atr > 0):
        return {"target": 0.0, "stop": None, "take": None}

    if long_signal:
        size = 0.0025 * hist.close[-1] / current_atr
        size = min(size, 1.0)
        size = max(size, 0.05)
        size = round(size / 0.05) * 0.05

