    short_signal = (rsi_prev >= 70.0) and (rsi_now < 70.0)

    # UTC calendar day tracking for the 2-entry-per-day cap
    current_day = int(hist.time[-1] / 86400000)
    if state.get("current_day", -1) != current_day:
        state["current_day"] = current_day
        state["entries_today"] = 0

    # Safety reset if position was flattened externally
    if pos == 0.0 and state.get("in_trade", 0) == 1:
        state["in_trade"] = 0

    # Opposite signal closes the current position (no reversal)
    if pos > 0 and short_signal:
        state["in_trade"] = 0
        return {"target": 0.0, "stop": None, "take": None}

    if pos < 0 and long_signal:
        state["in_trade"] = 0
        return {"target": 0.0, "stop": None, "take": None}

    # New entries only when flat
    if pos == 0.0:
        entries_today = int(state.get("entries_today", 0))

        if long_signal and entries_today < 2:
            atr_vals = ind.atr(hist, 14)
            state["in_trade"] = 1
            state["entry_atr"] = float(atr_vals[-1])
            state["last_fill_price"] = float(hist.close[-1])
            state["pyramid_count"] = 0
            state["entries_today"] = entries_today + 1
            return {"target": 0.5, "stop": None, "take": None}

        if short_signal and entries_today < 2:
            atr_vals = ind.atr(hist, 14)
            state["in_trade"] = 1
            state["entry_atr"] = float(atr_vals[-1])
            state["last_fill_price"] = float(hist.close[-1])
            state["pyramid_count"] = 0
            state["entries_today"] = entries_today + 1
            return {"target": -0.5, "stop": None, "take": None}

        return {"target": 0.0, "stop": None, "take": None}

    # Pyramiding: add 0.5 when price moves >= 2 entry ATR in favor from last fill
    if state.get("in_trade", 0) == 1:
        entry_atr = state.get("entry_atr", 0.0)
        last_fill = state.get("last_fill_price", 0.0)
        pyramid_count = int(state.get("pyramid_count", 0))

        if pyramid_count < 2 and entry_atr > 0.0:
            if pos > 0:
                # Long: close must be at least 2 ATR above last fill
                if hist.close[-1] >= last_fill + 2.0 * entry_atr:
                    new_target = min(pos + 0.5, 1.0)
                    if new_target > pos:
                        state["pyramid_count"] = pyramid_count + 1
                        state["last_fill_price"] = float(hist.close[-1])
                        return {"target": new_target, "stop": None, "take": None}
            elif pos < 0:
                # Short: close must be at least 2 ATR below last fill
                if hist.close[-1] <= last_fill - 2.0 * entry_atr:
                    new_target = max(pos - 0.5, -1.0)
                    if new_target < pos:
                        state["pyramid_count"] = pyramid_count + 1
                        state["last_fill_price"] = float(hist.close[-1])
                        return {"target": new_target, "stop": None, "take": None}

    # No action — hold current position
    return {"target": pos, "stop": None, "take": None}

