            if "be_moved" in state:
                del state["be_moved"]
            return {"target": 0.0, "stop": None, "take": None}

        # Stop management
        stop = None
        if direction == 1:
            # Long: check if at least 0.5 ATR in profit on close
            if not be_moved:
                if current_close >= entry_price + 0.5 * entry_atr:
                    state["be_moved"] = True
                    be_moved = True
            if be_moved:
                stop = entry_price
            else:
                stop = entry_price - entry_atr
        elif direction == -1:
            # Short: check if at least 0.5 ATR in profit on close
            if not be_moved:
                if current_close <= entry_price - 0.5 * entry_atr:
                    state["be_moved"] = True
                    be_moved = True
            if be_moved:
                stop = entry_price
            else:
                stop = entry_price + entry_atr

        return {"target": pos, "stop": stop, "take": None}

