def strategy(hist, state, pos, ind):
    # Compute indicators
    rsi = ind.rsi(hist.close, 14)
    atr = ind.atr(hist, 14)

    # 4h trend filter
    htf = hist.htf(240)
    if len(htf) < 51:
        return {"target": pos, "stop": None, "take": None}

    htf_close = htf.close
    htf_ema50 = ind.ema(htf_close, 50)

    # Current bar values
    cur_rsi = rsi[-1]
    prev_rsi = rsi[-2]
    cur_atr = atr[-1]
    cur_close = hist.close[-1]

    # Trend filter: last completed 4h close vs its 50 EMA
    htf_trend_up = htf_close[-1] > htf_ema50[-1]
    htf_trend_down = htf_close[-1] < htf_ema50[-1]

    # Cross signals (event-based)
    long_signal = (prev_rsi <= 25.0) and (cur_rsi > 25.0) and htf_trend_up
    short_signal = (prev_rsi >= 75.0) and (cur_rsi < 75.0) and htf_trend_down

    # If we were in a trade but position is now flat (take/stop filled), clear state
    if pos == 0 and "entry_price" in state:
        del state["entry_price"]
        del state["entry_atr"]
        del state["added"]

    # Manage open position
    if pos != 0:
        direction = 1 if pos > 0 else -1

        # Opposite signal -> go flat (desk convention: no reversal)
        if (direction == 1 and short_signal) or (direction == -1 and long_signal):
            if "entry_price" in state:
                del state["entry_price"]
                del state["entry_atr"]
                del state["added"]
            return {"target": 0, "stop": None, "take": None}

        entry_price = state.get("entry_price", cur_close)
        entry_atr = state.get("entry_atr", cur_atr)
        added = state.get("added", 0)

        # Take profit: 6 ATR from entry
        if direction == 1:
            take = entry_price + 6.0 * entry_atr
        else:
            take = entry_price - 6.0 * entry_atr

        # Pyramiding: one add of half size when price moves >= 2 ATR from last add price
        if not added:
            if direction == 1 and cur_close >= entry_price + 2.0 * entry_atr:
                state["added"] = 1
                return {"target": 1.0, "stop": None, "take": take}
            elif direction == -1 and cur_close <= entry_price - 2.0 * entry_atr:
                state["added"] = 1
                return {"target": -1.0, "stop": None, "take": take}

        return {"target": pos, "stop": None, "take": take}

    # Flat: look for new entry
    if long_signal:
        state["entry_price"] = cur_close
        state["entry_atr"] = cur_atr
        state["added"] = 0
        return {"target": 0.5, "stop": None, "take": cur_close + 6.0 * cur_atr}

    if short_signal:
        state["entry_price"] = cur_close
        state["entry_atr"] = cur_atr
        state["added"] = 0
        return {"target": -0.5, "stop": None, "take": cur_close - 6.0 * cur_atr}

    return {"target": pos, "stop": None, "take": None}

