def strategy(hist, state, pos, ind):
    t = len(hist) - 1

    # Compute indicators
    ema5 = ind.ema(hist.close, 5)
    ema200 = ind.ema(hist.close, 200)
    atr = ind.atr(hist, 14)

    # Current and previous EMA values
    ema5_now = ema5[-1]
    ema200_now = ema200[-1]
    ema5_prev = ema5[-2]
    ema200_prev = ema200[-2]
    atr_now = atr[-1]
    close_now = hist.close[-1]

    # Detect crossovers (strict cross events)
    cross_up = (ema5_prev <= ema200_prev) and (ema5_now > ema200_now)
    cross_down = (ema5_prev >= ema200_prev) and (ema5_now < ema200_now)

    # Track transition to flat for cooldown
    prev_pos = state.get('prev_pos', 0.0)
    if prev_pos != 0.0 and pos == 0.0:
        state['flat_since'] = float(t)
    state['prev_pos'] = float(pos)

    if pos != 0.0:
        # In a trade: check for opposite signal to close
        if pos > 0 and cross_down:
            return {"target": 0.0, "stop": None, "take": None}
        if pos < 0 and cross_up:
            return {"target": 0.0, "stop": None, "take": None}

        # Manage breakeven ratchet
        entry_price = state.get('entry_price', 0.0)
        entry_atr = state.get('entry_atr', 0.0)

        if pos > 0:
            # Long: check if close is at least 1.5 ATR above entry
            if close_now >= entry_price + 1.5 * entry_atr:
                state['breakeven'] = 1.0
            if state.get('breakeven', 0.0) >= 1.0:
                return {"target": pos, "stop": entry_price, "take": None}
            else:
                return {"target": pos, "stop": None, "take": None}
        else:
            # Short: check if close is at least 1.5 ATR below entry
            if close_now <= entry_price - 1.5 * entry_atr:
                state['breakeven'] = 1.0
            if state.get('breakeven', 0.0) >= 1.0:
                return {"target": pos, "stop": entry_price, "take": None}
            else:
                return {"target": pos, "stop": None, "take": None}

    else:
        # Flat: enforce cooldown of 48 bars
        flat_since = state.get('flat_since', -1000.0)
        if t - flat_since < 48:
            return {"target": 0.0, "stop": None, "take": None}

        # Look for entry signals
        if cross_up:
            state['entry_price'] = float(close_now)
            state['entry_atr'] = float(atr_now)
            state['breakeven'] = 0.0
            return {"target": 1.0, "stop": None, "take": None}
        elif cross_down:
            state['entry_price'] = float(close_now)
            state['entry_atr'] = float(atr_now)
            state['breakeven'] = 0.0
            return {"target": -1.0, "stop": None, "take": None}

        return {"target": 0.0, "stop": None, "take": None}

