def strategy(hist, state, pos, ind):
    t = len(hist) - 1

    if t < 96:
        return {"target": pos, "stop": None, "take": None}

    close = hist.close[-1]
    atr_arr = ind.atr(hist, 14)
    current_atr = atr_arr[-1]

    # Donchian channel: prior 96 bars (24 hours of 15-min bars)
    highest_96 = ind.highest(hist.high, 96)
    lowest_96 = ind.lowest(hist.low, 96)
    prior_96_high = highest_96[-2]
    prior_96_low = lowest_96[-2]

    # Daily entry cap tracking
    current_day = int(hist.time[-1] // 86400000)
    if state.get("last_day", -1) != current_day:
        state["last_day"] = current_day
        state["entries_today"] = 0

    # --- Position management ---
    if pos > 0:
        # Update best high since entry
        if hist.high[-1] > state.get("best_high", 0.0):
            state["best_high"] = hist.high[-1]

        entry_price = state["entry_price"]
        entry_atr = state["entry_atr"]
        best_high = state["best_high"]

        # Breakeven lock: once close >= entry + 1.5 ATR
        if not state.get("breakeven_locked", False):
            if close >= entry_price + 1.5 * entry_atr:
                state["breakeven_locked"] = True

        # Trailing stop: 1.5 ATR behind best high, floored at breakeven once locked
        trail_stop = best_high - 1.5 * entry_atr
        if state.get("breakeven_locked", False):
            stop = max(trail_stop, entry_price)
        else:
            stop = trail_stop

        # Donchian breakdown exit
        if close < prior_96_low:
            return {"target": 0.0, "stop": None, "take": None}

        return {"target": pos, "stop": stop, "take": None}

    # --- Entry logic (only when flat) ---
    if pos == 0.0:
        # New 24-hour high breakout, max 2 entries per day
        if close > prior_96_high and state.get("entries_today", 0) < 2:
            state["entries_today"] = state.get("entries_today", 0) + 1
            state["entry_price"] = close
            state["entry_atr"] = current_atr
            state["best_high"] = hist.high[-1]
            state["breakeven_locked"] = False
            initial_stop = hist.high[-1] - 1.5 * current_atr
            return {"target": 0.75, "stop": initial_stop, "take": None}

    return {"target": pos, "stop": None, "take": None}
